export type GeoCoord = [number, number];

export interface RawProvinceOutline {
  title: string;
  code: number | string;
  hub: GeoCoord;
  rings: string[][];
}

export interface ProvinceOutline {
  title: string;
  code: number | string;
  hub: GeoCoord;
  rings: GeoCoord[][][];
}

export interface RawHydroRiver {
  n: string;
  k: number;
  a?: number;
  v?: number;
  l: string[];
}

export interface RawHydroLake {
  n: string;
  k: number;
  a?: number;
  v?: number;
  r: string[];
}

export interface HydroRiver {
  name: string;
  rank: number;
  appear?: number;
  vanish?: number;
  lines: GeoCoord[][];
}

export interface HydroLake {
  name: string;
  rank: number;
  appear?: number;
  vanish?: number;
  rings: GeoCoord[][];
}

export interface HydroLabel {
  zh: string;
  en: string;
  coord: GeoCoord;
  kind: "trunk" | "river" | "lake";
  rot?: number;
  appear?: number;
  vanish?: number;
}

export interface JiangshanHydroData {
  rivers: HydroRiver[];
  lakes: HydroLake[];
  labels: HydroLabel[];
}

const VLQ_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+-";
const VLQ_LOOKUP = new Uint8Array(128);
for (let i = 0; i < 64; i++) {
  VLQ_LOOKUP[VLQ_ALPHABET.charCodeAt(i)] = i;
}

export function decodeVlqRing(s: string): GeoCoord[] {
  const r: GeoCoord[] = [];
  let i = 0;
  const n = s.length;
  let x = 0;
  let y = 0;
  while (i < n) {
    let b = 0;
    let sh = 0;
    let v = 0;
    do {
      b = VLQ_LOOKUP[s.charCodeAt(i++)] ?? 0;
      v |= (b & 31) << sh;
      sh += 5;
    } while (b >= 32);
    x += v & 1 ? ~(v >>> 1) : v >>> 1;
    sh = 0;
    v = 0;
    do {
      b = VLQ_LOOKUP[s.charCodeAt(i++)] ?? 0;
      v |= (b & 31) << sh;
      sh += 5;
    } while (b >= 32);
    y += v & 1 ? ~(v >>> 1) : v >>> 1;
    r.push([x / 100, y / 100]);
  }
  return r;
}

